var a=`0799-chakalaka`;var i=`world-0799`;var n=`ZA`;var s=`southern-africa`;var r=8;var o=35;var g={en:`Chakalaka`,ua:`Чакалака`};var l={en:`Chakalaka is a South Africa classic prepared with yellow onion, red bell pepper, scotch bonnet pepper, carrot. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Чакалака, страва кухні країни Південно-Африканська Республіка зі складниками: жовта цибуля, червоний солодкий перець, перець скотч-боннет, морква. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,190,`g`],[`red-bell-pepper`,260,`g`],[`sunflower-oil`,50,`ml`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Simmer vegetables until tender-crisp, stir in already-cooked canned beans and reduce to a thick spicy relish.`,ua:`Тушкуйте овочі до пружної м’якості, вмішайте готову консервовану квасолю й уваріть до густої гострої приправи.`,t:[`stewing`],m:19,i:[[`carrot`,230,`g`],[`white-cabbage`,280,`g`],[`tomato`,340,`g`],[`canned-white-beans`,300,`g`],[`tomato-paste`,35,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`ground-cumin`,5,`g`],[`parsley`,20,`g`]]}];var c={slug:a,id:i,country:`ZA`,region:s,servings:8,minutes:35,title:g,text:l,steps:d};export{n as country,c as default,i as id,o as minutes,s as region,r as servings,a as slug,d as steps,l as text,g as title};